	/**
	 * Default Constructor
	 */
    public PromotionService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new PromotionEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(PromotionRepository.class) );
		this.validator		= applicationContext.getBean(PromotionValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Promotion
	 */
		public Promotion createPromotion( CreatePromotionCommand command ) {

		Promotion entity = new Promotion();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setPromotionId( command.getPromotionId() );
            entity.setName( command.getName() );
            entity.setCode( command.getCode() );
            entity.setValue( command.getValue() );
            entity.setStartDate( command.getStartDate() );
            entity.setEndDate( command.getEndDate() );
            entity.setAsStackable( command.getAsStackable() );
            entity.setMaxRedemptions( command.getMaxRedemptions() );
            entity.setPromotionType( command.getPromotionType() );
            entity.setDiscountType( command.getDiscountType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Promotion {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdatePromotionCommand
	 * @return		Promotion
	 */
	public Promotion updatePromotion( UpdatePromotionCommand command ) {

		Promotion entity = new Promotion();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setPromotionId( command.getPromotionId() );
            entity.setName( command.getName() );
            entity.setCode( command.getCode() );
            entity.setValue( command.getValue() );
            entity.setStartDate( command.getStartDate() );
            entity.setEndDate( command.getEndDate() );
            entity.setAsStackable( command.getAsStackable() );
            entity.setMaxRedemptions( command.getMaxRedemptions() );
            entity.setMerchant( command.getMerchant() );
            entity.setChannels( command.getChannels() );
            entity.setApplicableProducts( command.getApplicableProducts() );
            entity.setApplicableCategories( command.getApplicableCategories() );
            entity.setCoupons( command.getCoupons() );
            entity.setPromotionType( command.getPromotionType() );
            entity.setDiscountType( command.getDiscountType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Promotion {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeletePromotionCommand
	 */
	public void delete( DeletePromotionCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getPromotionId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Promotion {0} ", id );

	}

	/**
	 * Method to retrieve the Promotion via PromotionFetchOneSummary
	 * @param 	summary PromotionFetchOneSummary
	 * @return 	PromotionFetchOneResponse
	 */
	public Promotion getPromotion( PromotionFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "PromotionFetchOneSummary arg cannot be null" );

		Promotion entity = null;
		UUID id = summary.getPromotionId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Promotion using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Promotions
	 *
	 * @return 	List<Promotion>
	 */
    public List<Promotion> getAllPromotion() {
		List<Promotion> list = projector.findAll( new FindAllPromotionQuery() );
		return list;
	}

	/**
	 * assign Merchant on Promotion
	 * @param		command AssignMerchantToPromotionCommand
	 */
	public void assignMerchant( AssignMerchantToPromotionCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignMerchant(command.getPromotionId(), command.getAssignment());

	}

